const BY_GLYPH: ReadonlyMap<string, IconEntry> = new Map(
  ICON_CATALOG.map((e) => [e.glyph, e]),
);
const BY_SLUG: ReadonlyMap<string, IconEntry> = new Map(
  ICON_CATALOG.map((e) => [e.slug, e]),
);

export function glyphToEntry(glyph: string): IconEntry | undefined {
  return BY_GLYPH.get(glyph);
}

// Resolve an MDI slug (e.g. "lightbulb") to its glyph, but only when the
// firmware actually bundles it — callers use this to keep to the renderable set.
export function slugToGlyph(slug: string): string | undefined {
  return BY_SLUG.get(slug)?.glyph;
}

export function filterIcons(query: string): readonly IconEntry[] {
  const q = query.trim().toLowerCase();
  if (q === "") return ICON_CATALOG;
  return ICON_CATALOG.filter((e) => e.slug.includes(q) || e.name.includes(q));
}
